// Official geometry (bundle module At) + rim formula (getRimCoordinates).
export const GEO = {
  gates: { center: { x: 1000, y: 1000 }, radius: 780 },
  hexagrams: { center: { x: 975, y: 970 }, radius: 900 },
  planets: { center: { x: 1000, y: 1000 }, radius: [622, 574, 530, 490, 454, 422] },
  zodiacWedgeRotate: i => 60 - 30 * i,
  zodiacSymbolRotate: i => 193.5 - 30 * i
};
export const evenRound = t => 2 * Math.round(t / 2);
export function rim(center, radius, index) {
  const s = 5.625 * index - 2.8;
  const a = (s * Math.PI) / 180;
  return `${evenRound(Math.round(center.x + radius * Math.cos(a)))}, ${evenRound(Math.round(center.y + radius * Math.sin(a)))}`;
}
